        var rangedItem=catalog.Items.First(i=>i.ClassId==2&&GearDesign.Targets(i).Contains(17)&&i.Number("SubclassID")==2);var armed=new Dictionary<int,CatalogItem>(worn){[15]=lookup[19019],[17]=rangedItem};view=new CharacterModelView();window=new Window{Content=view,Width=1000,Height=1000,Owner=this};window.Show();view.Bind(armed);await view.Loading;Assert(view.Scene is not null&&!view.Scene.Notes.Any(n=>n.StartsWith(rangedItem.Name+":")),"Melee scene loads with ranged hidden");view.RangedWeapons=true;await view.Loading;Assert(view.Scene is not null&&!view.Scene.Notes.Any(n=>n.StartsWith(rangedItem.Name+":")),"Ranged scene attaches bow to left hand");Assert(CharacterModelBuilder.WeaponAnchor(rangedItem)==2&&armed.ContainsKey(15)&&armed.ContainsKey(17),"Ranged uses hand attachment and preserves equipped melee and ranged items");await RenderEditorWindow(window,"ranged-character-preview");window.Close();
