        var heroes=await CharacterRepository.ListAsync();if(heroes.Count>0){var hero=heroes.OrderByDescending(c=>c.Level).First();var snapshot=await CharacterRepository.LoadAsync(hero);string saved=JsonSerializer.Serialize(snapshot);var armoryView=new ArmoryView();var armoryWindow=new Window{Content=armoryView,Width=1450,Height=950,Owner=this};armoryWindow.Show();await armoryView.Bind(snapshot,catalog,hero.Level);await armoryView.Loading;Assert(armoryView.Scene is not null,"Saved character model and equipment render in the armory: "+armoryView.Profile+" "+armoryView.Feedback);var originalSlots=armoryView.Equipment.ToDictionary(p=>p.Key,p=>p.Value.Id);armoryView.Swap(2,lookup[22419]);await armoryView.Loading;Assert(armoryView.Equipment[2].Id==22419&&JsonSerializer.Serialize(snapshot)==saved,"Armory swap updates preview without mutating the saved snapshot");await File.WriteAllTextAsync("artifacts/saved-character-model-details.json",JsonSerializer.Serialize(new{armoryView.Profile,armoryView.Scene!.BodyFile,armoryView.Scene.Equipped,armoryView.Scene.Applied,armoryView.Scene.Notes},new JsonSerializerOptions{WriteIndented=true}));await RenderEditorWindow(armoryWindow,"armory-character-preview");armoryWindow.Close();}
        await LoadCharacters();CharacterNav.IsChecked=true;await armory.Loading;await RenderEditorWindow(this,"unified-characters-preview");await ShowReferencePage("Spell catalog");referenceSearch.Clear();referenceFilters.Reset();referenceFilters.Trigger.SelectedItem="Chance on hit";Assert(referenceView!.Cast<ReferenceEntry>().Any()&&referenceView!.Cast<ReferenceEntry>().All(e=>e.Triggers.Contains("Chance on hit")),"Spell trigger filter uses all triggers assigned to each spell");referenceFilters.Reset();referenceSearch.Text="modify crit";Assert(referenceView!.Cast<ReferenceEntry>().Any()&&referenceView!.Cast<ReferenceEntry>().All(e=>e.Matches("modify crit")),"Spell search includes named aura fields");await RenderEditorWindow(this,"spell-catalog-all-fields-preview");await ShowReferencePage("Proc catalog");referenceFilters.Trigger.SelectedItem="Chance on hit";referenceSearch.Clear();Assert(referenceView!.Cast<ReferenceEntry>().Any()&&referenceView!.Cast<ReferenceEntry>().All(e=>e.Trigger=="Chance on hit"),"Proc trigger filter only includes the selected item-effect trigger");Assert(CatalogSearch.Item(lookup[22419],"plate shoulder")&&CatalogSearch.Item(lookup[22419],"dreadnaught"),"Item search matches multiple subtype, slot and name fields");
